"use client"
import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";


export default function NewPrescriptionPage() {
  const [selectedPatient, setSelectedPatient] = useState("");
  const [medicines, setMedicines] = useState([
    { name: "", dosage: "", duration: "", instructions: "" },
  ]);

  const handleMedicineChange = (idx, field, value) => {
    setMedicines((prev) =>
      prev.map((med, i) => (i === idx ? { ...med, [field]: value } : med))
    );
  };

  const addMedicine = () => {
    setMedicines((prev) => [
      ...prev,
      { name: "", dosage: "", duration: "", instructions: "" },
    ]);
  };

  const removeMedicine = (idx) => {
    setMedicines((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
  
    try {
      const prescriptionData = {
        patientId: id,
        medicines,
      };
  
      await createPrescription(prescriptionData);
      alert("Prescription submitted successfully!");
      router.push(`/doctor/patients/history/${id}`);
    } catch (err) {
      alert("Failed to submit prescription.");
    }
  };

  return (
    <div className="max-w-xl mx-auto py-8">
      <h1 className="text-2xl font-bold mb-6">New Prescription</h1>
      <Card className="rounded-lg p-6 shadow-md space-y-4">
        <form onSubmit={handleSubmit} className="space-y-4">
          {medicines.map((med, idx) => (
            <div key={idx} className="border rounded-lg p-4 space-y-2 relative bg-gray-50">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block mb-1 text-sm">Medicine Name</label>
                  <Input
                    value={med.name}
                    onChange={(e) => handleMedicineChange(idx, "name", e.target.value)}
                    required
                  />
                </div>
                <div>
                  <label className="block mb-1 text-sm">Dosage</label>
                  <Input
                    value={med.dosage}
                    onChange={(e) => handleMedicineChange(idx, "dosage", e.target.value)}
                    required
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block mb-1 text-sm">Duration</label>
                  <Input
                    value={med.duration}
                    onChange={(e) => handleMedicineChange(idx, "duration", e.target.value)}
                    required
                  />
                </div>
                <div>
                  <label className="block mb-1 text-sm">Instructions</label>
                  <Textarea
                    value={med.instructions}
                    onChange={(e) => handleMedicineChange(idx, "instructions", e.target.value)}
                    rows={2}
                    required
                  />
                </div>
              </div>
              {medicines.length > 1 && (
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="absolute top-2 right-2"
                  onClick={() => removeMedicine(idx)}
                >
                  Remove
                </Button>
              )}
            </div>
          ))}
          <Button type="button" variant="secondary" onClick={addMedicine} className="w-full">
            + Add Another Medicine
          </Button>
          <Button type="submit" className="w-full rounded-lg">
            Submit Prescription
          </Button>
        </form>
      </Card>
    </div>
  );
} 